Your expense tracker is below: add an amount, pick a category, and the total and category split update as you go. Entries stay only while this page is open, so note down anything you want to keep.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:Segoe UI,Arial,sans-serif;margin:0;padding:16px;background:#f6f7f5;color:#222}
  h2{margin:0 0 12px;font-size:18px}
  .card{background:#fff;border-radius:10px;padding:12px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}
  .row{display:flex;gap:8px;flex-wrap:wrap}
  input,select,button{font:inherit;padding:8px;border:1px solid #ccd;border-radius:6px}
  input{flex:1;min-width:90px}
  button{background:#2f7d5b;color:#fff;border:none;cursor:pointer}
  button.x{background:none;color:#a33;padding:2px 8px}
  .total{font-size:26px;font-weight:600}
  .muted{color:#667;font-size:13px}
  .bar{height:8px;background:#e3ebe6;border-radius:4px;overflow:hidden;margin:3px 0 8px}
  .bar div{height:100%;background:#2f7d5b}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee}
  .over{color:#b32}
</style>
</head>
<body>
<h2>Monthly expenses</h2>

<div class="card">
  <div class="row">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
  </div>
  <div class="row" style="margin-top:8px">
    <input id="note" type="text" placeholder="Note (optional)">
    <button onclick="add()">Add</button>
  </div>
</div>

<div class="card">
  <div class="muted">Spent this month</div>
  <div class="total" id="total">₹0</div>
  <div class="row" style="margin-top:8px;align-items:center">
    <span class="muted">Budget (₹)</span>
    <input id="budget" type="number" min="0" placeholder="e.g. 50000" oninput="render()">
  </div>
  <div class="muted" id="left" style="margin-top:6px"></div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">By category</div>
  <div id="cats"></div>
</div>

<div class="card">
  <div class="muted" style="margin-bottom:6px">Entries</div>
  <div id="list"></div>
</div>

<script>
var items=[];
function inr(n){return '₹'+Math.round(n).toLocaleString('en-IN');}
function add(){
  var a=parseFloat(document.getElementById('amt').value);
  if(!(a>0))return;
  items.push({a:a,c:document.getElementById('cat').value,n:document.getElementById('note').value});
  document.getElementById('amt').value='';
  document.getElementById('note').value='';
  render();
}
function del(i){items.splice(i,1);render();}
function render(){
  var t=0,by={};
  items.forEach(function(x){t+=x.a;by[x.c]=(by[x.c]||0)+x.a;});
  document.getElementById('total').textContent=inr(t);
  var b=parseFloat(document.getElementById('budget').value);
  var l=document.getElementById('left');
  if(b>0){
    var r=b-t;
    l.className=r<0?'muted over':'muted';
    l.textContent=r<0?('Over budget by '+inr(-r)):(inr(r)+' left of '+inr(b));
  }else{l.textContent='';}
  var c='';
  Object.keys(by).sort(function(p,q){return by[q]-by[p];}).forEach(function(k){
    var p=t?Math.round(by[k]/t*100):0;
    c+='<div class="row" style="justify-content:space-between"><span>'+k+'</span><span>'+inr(by[k])+' ('+p+'%)</span></div><div class="bar"><div style="width:'+p+'%"></div></div>';
  });
  document.getElementById('cats').innerHTML=c||'<span class="muted">Nothing yet</span>';
  var h='';
  items.slice().reverse().forEach(function(x,j){
    var i=items.length-1-j;
    var n=x.n.replace(/</g,'&lt;');
    h+='<div class="item"><span>'+x.c+(n?' · <span class="muted">'+n+'</span>':'')+'</span><span>'+inr(x.a)+' <button class="x" onclick="del('+i+')">✕</button></span></div>';
  });
  document.getElementById('list').innerHTML=h||'<span class="muted">No entries</span>';
}
render();
</script>
</body>
</html>
```
